            <span class="font-bold text-orange-600 dark:text-orange-400 font-mono text-[11px]">${user.account_tier === 'STUDENT' ? 'Sinh Viên' : (user.account_tier === 'ENTERPRISE' ? 'Doanh Nghiệp' : 'Cá Nhân')}</span>
